#[test]fn grouped_at_block_positions_and_lifecycle(){use combine_mobs::*;let mut m=CombineMobs::default();let adult=Key::at("minecraft:chicken",false,[-0.1,64.0,-0.1]);assert_eq!(adult.position,((0x3ffffffi64)<<38)|((0x3ffffffi64)<<12)|64);assert!(!m.track(true,adult.clone(),0,false));assert!(m.track(true,adult.clone(),0,false));assert_eq!(m.count(true,&adult),2);assert!(!m.track(true,Key::at("minecraft:chicken",true,[-0.1,64.0,-0.1]),0,false));assert!(!m.track(true,adult.clone(),1,false));m.clear_render();assert_eq!(m.count(true,&adult),1);assert!(!m.track(true,adult.clone(),0,true));assert!(m.track(true,adult.clone(),0,true));assert_eq!(m.count(true,&adult),2);m.disabled();assert_eq!(m.count(true,&adult),1);assert_eq!(m.count(false,&adult),1);}
